        public static UnitConverterDensityUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterDensityUnit>();
            for (int i = 0; i < 65; i++) if (GetUnitSystem((UnitConverterDensityUnit)i) == system) units.Add((UnitConverterDensityUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterDensityUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterDensityUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterDensityUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterDensityUnit)id : default(UnitConverterDensityUnit); return success;
        }

        public static UnitConverterDensityUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterDensityUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous Density unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterDensityValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterDensityValue(value, (UnitConverterDensityUnit)id) : default(UnitConverterDensityValue); return success;
        }

        public static UnitConverterDensityValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterDensityValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous Density unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterDensityUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


